/* ════════════════════════════════════════════════════════════
   BREW & BLOOM CAFÉ — style.css
   Brand palette:
   --cream:       #fdf6ed   (warm cream background)
   --espresso:    #3b1f0e   (dark espresso brown)
   --latte:       #8b5a2b   (medium latte brown)
   --caramel:     #c4721e   (terracotta orange / caramel)
   --sage:        #6b8e6b   (muted sage green)
   --sage-light:  #e8f0e8   (soft sage tint)
   --sand:        #f0e4d0   (warm sand card bg)
   ════════════════════════════════════════════════════════════ */

/* ── RESET & CUSTOM PROPERTIES ─────────────────────────── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --cream:       #fdf6ed;
  --cream-dark:  #f5e9d5;
  --espresso:    #3b1f0e;
  --espresso-2:  #2a1508;
  --latte:       #8b5a2b;
  --caramel:     #c4721e;
  --caramel-lt:  #e8a050;
  --sage:        #6b8e6b;
  --sage-lt:     #e8f0e8;
  --sand:        #f0e4d0;
  --sand-dark:   #e5d3b8;
  --white:       #ffffff;
  --text:        #2d1a0e;
  --text-muted:  #7a5a3a;
  --radius-sm:   8px;
  --radius-md:   14px;
  --radius-lg:   22px;
  --radius-xl:   32px;
  --shadow-sm:   0 2px 8px rgba(59,31,14,.08);
  --shadow-md:   0 6px 24px rgba(59,31,14,.12);
  --shadow-lg:   0 16px 48px rgba(59,31,14,.16);
  --nav-h:       72px;
  --transition:  0.3s cubic-bezier(0.4,0,0.2,1);
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: var(--nav-h);
  font-size: 16px;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: 'Inter', sans-serif;
  background: var(--cream);
  color: var(--text);
  line-height: 1.65;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }
ul { list-style: none; }
address { font-style: normal; }

/* ── TYPOGRAPHY ────────────────────────────────────────── */
h1, h2, h3, h4, h5 {
  font-family: 'Playfair Display', serif;
  line-height: 1.25;
  color: var(--espresso);
}

.section-eyebrow {
  font-family: 'Dancing Script', cursive;
  font-size: 1.25rem;
  color: var(--caramel);
  display: block;
  margin-bottom: 0.4rem;
}

.section-title {
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 700;
  margin-bottom: 1rem;
}

.section-desc {
  color: var(--text-muted);
  max-width: 56ch;
  margin: 0 auto;
}

.section-header {
  text-align: center;
  margin-bottom: 3rem;
}

/* ── CONTAINER ─────────────────────────────────────────── */
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* ── SECTION ───────────────────────────────────────────── */
.section {
  padding: 5rem 0;
}

/* ── BUTTONS ───────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.7rem 1.6rem;
  border-radius: 100px;
  font-weight: 600;
  font-size: 0.925rem;
  letter-spacing: 0.02em;
  transition: all var(--transition);
  white-space: nowrap;
  cursor: pointer;
  border: 2px solid transparent;
}

.btn-lg {
  padding: 0.9rem 2rem;
  font-size: 1rem;
}

.btn-sm {
  padding: 0.45rem 1.1rem;
  font-size: 0.8rem;
}

.btn-primary {
  background: var(--espresso);
  color: var(--cream);
  border-color: var(--espresso);
}
.btn-primary:hover, .btn-primary:focus-visible {
  background: var(--caramel);
  border-color: var(--caramel);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(196,114,30,.35);
}

.btn-ghost {
  background: rgba(255,255,255,0.12);
  color: var(--white);
  border-color: rgba(255,255,255,0.5);
  backdrop-filter: blur(8px);
}
.btn-ghost:hover, .btn-ghost:focus-visible {
  background: rgba(255,255,255,0.22);
  border-color: rgba(255,255,255,0.9);
  transform: translateY(-2px);
}

.btn-whatsapp {
  background: #25D366;
  color: #fff;
  border-color: #25D366;
  font-weight: 700;
}
.btn-whatsapp:hover, .btn-whatsapp:focus-visible {
  background: #128C7E;
  border-color: #128C7E;
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(37,211,102,.4);
}

.btn-order {
  background: var(--caramel);
  color: #fff;
  border-color: var(--caramel);
  padding: 0.4rem 1rem;
  font-size: 0.78rem;
}
.btn-order:hover, .btn-order:focus-visible {
  background: var(--espresso);
  border-color: var(--espresso);
  transform: translateY(-1px);
}

/* Focus styles for accessibility */
:focus-visible {
  outline: 3px solid var(--caramel);
  outline-offset: 3px;
}

/* ════════════════════════════════════════════════════════════
   NAVIGATION
   ════════════════════════════════════════════════════════════ */
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 1000;
  height: var(--nav-h);
  background: transparent;
  transition: background var(--transition), box-shadow var(--transition);
}

.navbar.scrolled {
  background: rgba(253,246,237,0.96);
  backdrop-filter: blur(16px);
  box-shadow: 0 1px 0 rgba(59,31,14,.08), var(--shadow-sm);
}

.nav-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.nav-logo {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  flex-shrink: 0;
  text-decoration: none;
}

.logo-icon {
  font-size: 1.8rem;
  line-height: 1;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,.15));
}

.logo-text {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.logo-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.15rem;
  font-weight: 700;
  color: var(--espresso);
  transition: color var(--transition);
}

.navbar:not(.scrolled) .logo-name,
.navbar:not(.scrolled) .logo-tagline {
  color: var(--white);
}

.logo-tagline {
  font-size: 0.55rem;
  letter-spacing: 0.25em;
  font-weight: 500;
  color: var(--latte);
  margin-top: 1px;
}

.navbar:not(.scrolled) .logo-tagline { color: rgba(255,255,255,0.7); }

.nav-links {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  margin-left: auto;
}

.nav-link {
  padding: 0.4rem 0.85rem;
  border-radius: 100px;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--espresso);
  transition: all var(--transition);
  position: relative;
}

.navbar:not(.scrolled) .nav-link { color: rgba(255,255,255,0.9); }
.navbar:not(.scrolled) .nav-link:hover,
.navbar:not(.scrolled) .nav-link.active {
  color: #fff;
  background: rgba(255,255,255,0.15);
}

.nav-link:hover, .nav-link.active {
  color: var(--caramel);
  background: rgba(196,114,30,.08);
}

.nav-cta {
  flex-shrink: 0;
  font-size: 0.85rem;
  padding: 0.5rem 1.2rem;
}

.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 40px;
  height: 40px;
  padding: 6px;
  border-radius: var(--radius-sm);
  flex-shrink: 0;
}

.ham-bar {
  display: block;
  width: 100%;
  height: 2px;
  background: var(--espresso);
  border-radius: 2px;
  transition: all var(--transition);
}

.navbar:not(.scrolled) .ham-bar { background: #fff; }

.hamburger.open .ham-bar:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open .ham-bar:nth-child(2) { opacity: 0; transform: scaleX(0); }
.hamburger.open .ham-bar:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

/* ════════════════════════════════════════════════════════════
   HERO
   ════════════════════════════════════════════════════════════ */
.hero {
  position: relative;
  min-height: 100dvh;
  display: flex;
  align-items: center;
  overflow: hidden;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    url('https://images.unsplash.com/photo-1501339847302-ac426a4a7cbb?w=1920&q=80&auto=format&fit=crop') center/cover no-repeat;
  transform: scale(1.05);
  transition: transform 8s ease-out;
  will-change: transform;
}

.hero:hover .hero-bg { transform: scale(1.0); }

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(
    135deg,
    rgba(42,21,8,0.78) 0%,
    rgba(59,31,14,0.6) 50%,
    rgba(42,21,8,0.45) 100%
  );
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 1.5rem;
  padding-top: var(--nav-h);
  width: 100%;
}

.hero-eyebrow {
  font-family: 'Dancing Script', cursive;
  font-size: 1.4rem;
  color: var(--caramel-lt);
  display: block;
  margin-bottom: 1rem;
  opacity: 0;
  animation: fadeUp 0.7s 0.3s forwards;
}

.hero-headline {
  font-size: clamp(2.6rem, 6vw, 4.5rem);
  font-weight: 700;
  color: var(--white);
  line-height: 1.15;
  margin-bottom: 1.5rem;
  opacity: 0;
  animation: fadeUp 0.7s 0.5s forwards;
}

.hero-headline em {
  font-style: italic;
  color: var(--caramel-lt);
}

.hero-desc {
  color: rgba(255,255,255,0.82);
  font-size: 1.1rem;
  max-width: 50ch;
  margin-bottom: 2.2rem;
  line-height: 1.7;
  opacity: 0;
  animation: fadeUp 0.7s 0.7s forwards;
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  margin-bottom: 3rem;
  opacity: 0;
  animation: fadeUp 0.7s 0.9s forwards;
}

.hero-badges {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  opacity: 0;
  animation: fadeUp 0.7s 1.1s forwards;
}

.badge {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
}

.badge-num {
  font-family: 'Playfair Display', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--caramel-lt);
}

.badge-label {
  font-size: 0.75rem;
  color: rgba(255,255,255,0.65);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.badge-sep {
  width: 1px;
  height: 36px;
  background: rgba(255,255,255,0.2);
}

.hero-scroll-hint {
  position: absolute;
  bottom: 2.5rem;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  color: rgba(255,255,255,0.5);
  font-size: 0.65rem;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  animation: fadeUp 1s 1.5s forwards;
  opacity: 0;
}

.scroll-arrow {
  width: 20px;
  height: 20px;
  border-right: 2px solid rgba(255,255,255,0.4);
  border-bottom: 2px solid rgba(255,255,255,0.4);
  transform: rotate(45deg);
  animation: bounce 1.5s ease infinite;
}

/* ════════════════════════════════════════════════════════════
   ANNOUNCEMENT STRIP
   ════════════════════════════════════════════════════════════ */
.announcement-strip {
  background: var(--espresso);
  padding: 0.7rem 0;
  overflow: hidden;
  white-space: nowrap;
}

.strip-track {
  display: inline-flex;
  animation: marquee 28s linear infinite;
}

.strip-track span {
  color: var(--caramel-lt);
  font-size: 0.85rem;
  font-weight: 500;
  letter-spacing: 0.03em;
  padding-right: 2rem;
}

/* ════════════════════════════════════════════════════════════
   MENU SECTION
   ════════════════════════════════════════════════════════════ */
.menu-section {
  background: var(--cream);
}

.menu-tabs {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  flex-wrap: wrap;
  margin-bottom: 2.5rem;
  background: var(--sand);
  border-radius: var(--radius-xl);
  padding: 0.4rem;
  max-width: 680px;
  margin-left: auto;
  margin-right: auto;
}

.tab-btn {
  padding: 0.55rem 1.2rem;
  border-radius: 100px;
  font-size: 0.88rem;
  font-weight: 500;
  color: var(--latte);
  background: transparent;
  transition: all var(--transition);
  border: none;
  cursor: pointer;
  white-space: nowrap;
}

.tab-btn.active, .tab-btn:hover {
  background: var(--espresso);
  color: var(--cream);
  box-shadow: var(--shadow-sm);
}

.tab-panel { display: none; }
.tab-panel.active { display: block; animation: fadeIn 0.4s ease; }

.menu-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1.5rem;
}

.menu-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  position: relative;
}

.menu-card:hover {
  transform: translateY(-6px);
  box-shadow: var(--shadow-lg);
}

.menu-card.featured-item {
  border: 2px solid var(--caramel);
}

.menu-card-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}

.menu-emoji {
  font-size: 3.5rem;
  filter: drop-shadow(0 4px 12px rgba(0,0,0,0.3));
  transition: transform var(--transition);
}

.menu-card:hover .menu-emoji { transform: scale(1.15) rotate(-3deg); }

.featured-tag {
  position: absolute;
  top: 0.6rem;
  right: 0.6rem;
  background: var(--caramel);
  color: #fff;
  font-size: 0.65rem;
  font-weight: 700;
  padding: 0.25rem 0.6rem;
  border-radius: 100px;
  letter-spacing: 0.03em;
}

.menu-card-body {
  padding: 1.2rem 1.25rem 1.25rem;
}

.menu-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.menu-item-name {
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--espresso);
}

.menu-badge {
  flex-shrink: 0;
  background: var(--sand);
  color: var(--latte);
  font-size: 0.65rem;
  font-weight: 600;
  padding: 0.2rem 0.55rem;
  border-radius: 100px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.menu-badge.badge-special { background: #fff4e6; color: var(--caramel); }
.menu-badge.badge-cold    { background: #e6f4ff; color: #2272a8; }
.menu-badge.badge-fresh   { background: #eef5ee; color: var(--sage); }

.menu-item-desc {
  font-size: 0.82rem;
  color: var(--text-muted);
  line-height: 1.5;
  margin-bottom: 1rem;
}

.menu-card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
}

.menu-price {
  font-family: 'Playfair Display', serif;
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--caramel);
}

.menu-disclaimer {
  text-align: center;
  margin-top: 2.5rem;
  color: var(--text-muted);
  font-size: 0.82rem;
  background: var(--sand);
  padding: 0.75rem 1.5rem;
  border-radius: var(--radius-md);
  display: inline-block;
  width: 100%;
  max-width: 660px;
  margin-left: auto;
  margin-right: auto;
}

/* ════════════════════════════════════════════════════════════
   ABOUT SECTION
   ════════════════════════════════════════════════════════════ */
.about-section {
  background: var(--cream-dark);
}

.about-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.about-imagery {
  position: relative;
  height: 520px;
}

.about-img-main {
  position: absolute;
  top: 0; left: 0;
  width: 75%;
  height: 78%;
  border-radius: var(--radius-xl);
  background: linear-gradient(160deg, #3b1f0e 0%, #8b5a2b 50%, #c4721e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  overflow: hidden;
  background-image: url('https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=800&q=80&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
}

.about-img-accent {
  position: absolute;
  bottom: 0; right: 0;
  width: 52%;
  height: 48%;
  border-radius: var(--radius-lg);
  background: linear-gradient(160deg, #5c3317 0%, #c4721e 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--shadow-lg);
  border: 4px solid var(--cream-dark);
  overflow: hidden;
  background-image: url('https://images.unsplash.com/photo-1447933601403-0c6688de566e?w=600&q=80&auto=format&fit=crop');
  background-size: cover;
  background-position: center;
}

.about-img-icon {
  font-size: 3.5rem;
  filter: drop-shadow(0 4px 12px rgba(0,0,0,.4));
}

.about-stat-card {
  position: absolute;
  top: 50%;
  right: 0;
  transform: translate(20%, -50%);
  background: var(--espresso);
  color: var(--cream);
  padding: 1rem 1.4rem;
  border-radius: var(--radius-md);
  text-align: center;
  box-shadow: var(--shadow-md);
  z-index: 2;
}

.stat-num {
  display: block;
  font-family: 'Playfair Display', serif;
  font-size: 2rem;
  font-weight: 700;
  color: var(--caramel-lt);
  line-height: 1;
}

.stat-label {
  font-size: 0.7rem;
  opacity: 0.8;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-top: 0.25rem;
}

.about-content { max-width: 520px; }

.about-para {
  color: var(--text-muted);
  margin-bottom: 1.25rem;
  line-height: 1.75;
}

.about-values {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin: 2rem 0;
}

.value-item {
  display: flex;
  align-items: flex-start;
  gap: 1rem;
}

.value-icon {
  font-size: 1.6rem;
  flex-shrink: 0;
  width: 44px;
  height: 44px;
  background: var(--sand);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
}

.value-item strong {
  display: block;
  font-size: 0.95rem;
  color: var(--espresso);
  margin-bottom: 0.15rem;
}

.value-item p {
  font-size: 0.82rem;
  color: var(--text-muted);
}

/* ════════════════════════════════════════════════════════════
   GALLERY SECTION
   ════════════════════════════════════════════════════════════ */
.gallery-section {
  background: var(--espresso-2);
  padding: 5rem 0;
}

.gallery-section .section-eyebrow { color: var(--caramel-lt); }
.gallery-section .section-title   { color: var(--cream); }
.gallery-section .section-desc    { color: rgba(255,255,255,0.55); }

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  grid-template-rows: auto auto;
  gap: 1rem;
}

.gallery-item {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  cursor: pointer;
  min-height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.gallery-tall {
  grid-row: span 2;
  min-height: 460px;
}

.gallery-wide {
  grid-column: span 2;
}

.gallery-bg {
  position: absolute;
  inset: 0;
  transition: transform 0.6s ease;
}

.gallery-item:hover .gallery-bg { transform: scale(1.06); }

.gallery-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(42,21,8,.75) 0%, transparent 60%);
  opacity: 0;
  transition: opacity var(--transition);
  display: flex;
  align-items: flex-end;
  padding: 1.25rem;
}

.gallery-item:hover .gallery-overlay,
.gallery-item:focus-visible .gallery-overlay { opacity: 1; }

.gallery-label {
  color: #fff;
  font-family: 'Playfair Display', serif;
  font-size: 1.05rem;
  font-weight: 600;
}

.gallery-emoji {
  font-size: 3.5rem;
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 4px 16px rgba(0,0,0,.4));
  transition: transform 0.5s ease;
}

.gallery-item:hover .gallery-emoji { transform: scale(1.2); }

/* ════════════════════════════════════════════════════════════
   BESTSELLERS SECTION
   ════════════════════════════════════════════════════════════ */
