/**
 * Brew & Bloom Café — script.js
 *
 * ┌─────────────────────────────────────────────────────────┐
 * │  CONFIGURABLE: WhatsApp Number                          │
 * │  Change WHATSAPP_NUMBER to your actual phone number.    │
 * │  Format: country code + number, no spaces or symbols.   │
 * │  Example India: "919876543210"                          │
 * └─────────────────────────────────────────────────────────┘
 */
const WHATSAPP_NUMBER = "910000000000"; // ← EDIT THIS


/* ══════════════════════════════════════════════════════════
   WHATSAPP LINK BUILDER
   Generates a prefilled wa.me link with the selected item.
   ══════════════════════════════════════════════════════════ */
function buildWhatsAppLink(item) {
  const message = encodeURIComponent(
    `Hi! I'd like to order ${item} from Brew & Bloom Café, Haldia. Please confirm availability. 😊`
  );
  return `https://wa.me/${WHATSAPP_NUMBER}?text=${message}`;
}

/**
 * Attach the correct WhatsApp href to every element with
 * class .whatsapp-order (uses data-item attribute for the message).
 */
function initWhatsAppLinks() {
  document.querySelectorAll(".whatsapp-order").forEach((el) => {
    const item = el.dataset.item || "something from your menu";
    const link = buildWhatsAppLink(item);

    if (el.tagName === "A") {
      el.href = link;
      el.target = "_blank";
      el.rel = "noopener noreferrer";
    } else if (el.tagName === "BUTTON") {
      el.addEventListener("click", () => {
        window.open(link, "_blank", "noopener,noreferrer");
      });
    }
  });
}


/* ══════════════════════════════════════════════════════════
   STICKY NAVBAR
   Adds .scrolled class when page scrolls past the hero.
   ══════════════════════════════════════════════════════════ */
function initNavbar() {
  const navbar = document.getElementById("navbar");
  if (!navbar) return;

  const onScroll = () => {
    navbar.classList.toggle("scrolled", window.scrollY > 60);
  };

  window.addEventListener("scroll", onScroll, { passive: true });
  onScroll(); // run once on load
}


/* ══════════════════════════════════════════════════════════
   ACTIVE NAV LINK  (IntersectionObserver)
   ══════════════════════════════════════════════════════════ */
function initActiveNavLinks() {
  const sections = document.querySelectorAll("section[id], .hero[id]");
  const navLinks = document.querySelectorAll(".nav-link");
  if (!sections.length || !navLinks.length) return;

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          const id = entry.target.id;
          navLinks.forEach((link) => {
            const href = link.getAttribute("href");
            link.classList.toggle("active", href === `#${id}`);
          });
        }
      });
    },
    { rootMargin: "-40% 0px -55% 0px" }
  );

  sections.forEach((s) => observer.observe(s));
}


/* ══════════════════════════════════════════════════════════
   HAMBURGER MOBILE MENU
   ══════════════════════════════════════════════════════════ */
function initHamburger() {
  const btn   = document.getElementById("hamburger");
  const links = document.getElementById("navLinks");
  if (!btn || !links) return;

  const close = () => {
    btn.classList.remove("open");
    links.classList.remove("open");
    btn.setAttribute("aria-expanded", "false");
  };

  btn.addEventListener("click", () => {
    const isOpen = btn.classList.toggle("open");
    links.classList.toggle("open", isOpen);
    btn.setAttribute("aria-expanded", String(isOpen));
  });

  // Close on nav link click
  links.querySelectorAll(".nav-link").forEach((link) => {
    link.addEventListener("click", close);
  });

  // Close on outside click
  document.addEventListener("click", (e) => {
    if (!btn.contains(e.target) && !links.contains(e.target)) close();
  });

  // Close on Escape
  document.addEventListener("keydown", (e) => {
    if (e.key === "Escape") close();
  });
}


/* ══════════════════════════════════════════════════════════
   MENU CATEGORY TABS
   ══════════════════════════════════════════════════════════ */
function initMenuTabs() {
  const tabs   = document.querySelectorAll(".tab-btn");
  const panels = document.querySelectorAll(".tab-panel");

  tabs.forEach((tab) => {
    tab.addEventListener("click", () => {
      const target = tab.dataset.tab;

      // Update tab buttons
      tabs.forEach((t) => {
        t.classList.toggle("active", t === tab);
        t.setAttribute("aria-selected", t === tab ? "true" : "false");
      });

      // Show/hide panels
      panels.forEach((panel) => {
        const isActive = panel.id === `tab-${target}`;
        panel.classList.toggle("active", isActive);
        if (isActive) {
          panel.removeAttribute("hidden");
        } else {
          panel.setAttribute("hidden", "");
        }
      });
    });
  });
}


/* ══════════════════════════════════════════════════════════
   SCROLL REVEAL  (IntersectionObserver)
   ══════════════════════════════════════════════════════════ */
function initScrollReveal() {
  // Assign .reveal to main content blocks
  const revealSelectors = [
    ".menu-card",
    ".bestseller-card",
    ".info-card",
    ".about-values .value-item",
    ".gallery-item",
    ".contact-item",
    ".about-content",
  ];

  revealSelectors.forEach((sel) => {
    document.querySelectorAll(sel).forEach((el, i) => {
      el.classList.add("reveal");
      el.style.transitionDelay = `${i * 60}ms`;
    });
  });

  // Section headers
  document.querySelectorAll(".section-header, .about-imagery").forEach((el) => {
    el.classList.add("reveal");
  });

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          entry.target.classList.add("visible");
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.12 }
  );

  document.querySelectorAll(".reveal").forEach((el) => observer.observe(el));
}


/* ══════════════════════════════════════════════════════════
   BACK TO TOP BUTTON
   ══════════════════════════════════════════════════════════ */
function initBackToTop() {
  const btn = document.getElementById("backToTop");
  if (!btn) return;

  window.addEventListener(
    "scroll",
    () => {
      btn.classList.toggle("visible", window.scrollY > 500);
    },
    { passive: true }
  );

  btn.addEventListener("click", () => {
    window.scrollTo({ top: 0, behavior: "smooth" });
  });
}


/* ══════════════════════════════════════════════════════════
   SMOOTH SCROLL for anchor links (fallback for older browsers)
   ══════════════════════════════════════════════════════════ */
function initSmoothScroll() {
  document.querySelectorAll('a[href^="#"]').forEach((anchor) => {
    anchor.addEventListener("click", (e) => {
      const targetId = anchor.getAttribute("href");
      if (targetId === "#") return;
      const target = document.querySelector(targetId);
      if (!target) return;
      e.preventDefault();
      target.scrollIntoView({ behavior: "smooth", block: "start" });
    });
  });
}


/* ══════════════════════════════════════════════════════════
   GALLERY KEYBOARD ACCESS
   ══════════════════════════════════════════════════════════ */
function initGalleryA11y() {
  document.querySelectorAll(".gallery-item[tabindex]").forEach((item) => {
    item.addEventListener("keydown", (e) => {
      if (e.key === "Enter" || e.key === " ") {
        e.preventDefault();
        // Toggle overlay visibility via focus (handled in CSS)
        item.focus();
      }
    });
  });
}


/* ══════════════════════════════════════════════════════════
   HERO PARALLAX  (subtle, only on desktop)
   ══════════════════════════════════════════════════════════ */
function initHeroParallax() {
  const heroBg = document.querySelector(".hero-bg");
  if (!heroBg) return;

  let ticking = false;

  const onScroll = () => {
    if (!ticking) {
      requestAnimationFrame(() => {
        if (window.scrollY < window.innerHeight) {
          const offset = window.scrollY * 0.25;
          heroBg.style.transform = `scale(1.05) translateY(${offset}px)`;
        }
        ticking = false;
      });
      ticking = true;
    }
  };

  // Only on desktop (avoid jank on mobile)
  if (window.innerWidth > 900) {
    window.addEventListener("scroll", onScroll, { passive: true });
  }
}


/* ══════════════════════════════════════════════════════════
   INIT — run after DOM is ready
   ══════════════════════════════════════════════════════════ */
