/**
 * ╔══════════════════════════════════════════════════════════╗
 * ║  BREW & BLOOM CAFÉ — CENTRAL CONFIGURATION              ║
 * ║  Edit this file to customise your café platform.        ║
 * ╚══════════════════════════════════════════════════════════╝
 */

const CONFIG = {

  /* ── CAFÉ IDENTITY ─────────────────────────────────────── */
  cafe: {
    name:        'Brew & Bloom Café',
    tagline:     'Good Coffee. Slow Moments. Beautiful Days.',
    address:     '[Sample Address], Near [Landmark], Haldia, West Bengal – 721657',
    city:        'Haldia, West Bengal',
    phone:       '+91 00000 00000',       // ← Replace with real number
    email:       'hello@brewandbloom.in', // ← Replace with real email
    whatsapp:    '910000000000',          // ← Replace (country code + number, no symbols)
    instagram:   '#',                     // ← Replace with Instagram URL
    facebook:    '#',                     // ← Replace with Facebook URL
  },

  /* ── RESTAURANT LOCATION ───────────────────────────────── */
  // ⚠️ IMPORTANT: Replace with your actual café GPS coordinates.
  // To find: Google Maps → right-click your location → "What's here?"
  restaurant: {
    lat:  22.0667,   // ← Replace: Haldia approximate coordinates
    lng:  88.0686,   // ← Replace: Haldia approximate coordinates
    name: 'Brew & Bloom Café',
    address: '[Sample Address], Haldia, WB',
  },

  /* ── DELIVERY SETTINGS ─────────────────────────────────── */
  delivery: {
    radiusKm:        10,     // Max delivery radius in km
    baseCharge:      30,     // ₹ base delivery charge
    perKmCharge:     5,      // ₹ per km beyond 3km
    freeAbove:       500,    // ₹ order total for free delivery
    freeRadiusKm:    3,      // km within which delivery is free (if order >= freeAbove)
    minOrderAmount:  100,    // ₹ minimum order
    estimatedMinBase: 30,    // minutes base prep + short delivery
    perKmMinutes:     3,     // additional minutes per km
  },

  /* ── TAXES ─────────────────────────────────────────────── */
  tax: {
    gstPercent: 5,   // % GST applied on food subtotal
    // Set to 0 to disable tax display
  },

  /* ── OPENING HOURS ─────────────────────────────────────── */
  hours: {
    'Mon–Fri': { open: '08:00', close: '21:00' },
    'Saturday': { open: '08:00', close: '22:00' },
    'Sunday':   { open: '09:00', close: '20:00' },
  },

  /* ── SUPABASE (Backend) ─────────────────────────────────── */
  // Sign up free at https://supabase.com → create project → Settings → API
  // NEVER commit real keys to public GitHub.
  // Use environment variables in production (Vercel env vars).
  supabase: {
    url:    typeof __SUPABASE_URL__    !== 'undefined' ? __SUPABASE_URL__    : '',
    anonKey: typeof __SUPABASE_ANON__ !== 'undefined' ? __SUPABASE_ANON__   : '',
    // If both are empty, the app runs in localStorage-only demo mode.
  },

  /* ── PAYMENT ────────────────────────────────────────────── */
  payment: {
    codEnabled:     true,
    upiEnabled:     true,
    upiId:          'yourname@upi',  // ← Replace with your UPI ID
    upiName:        'Brew & Bloom Café',
    // Online gateway (Razorpay / Cashfree): set keyId below.
    // Leave empty to show demo-mode UPI only.
    razorpayKeyId:  '',              // ← Optional: Razorpay key_id
  },

  /* ── ORDER TRACKING ─────────────────────────────────────── */
  tracking: {
    // If Supabase is not configured, demo mode kicks in automatically.
    // Demo simulates a driver moving from restaurant to customer.
    locationUpdateIntervalMs: 5000,  // How often driver app sends GPS (ms)
    demoRouteSteps: 20,              // Steps in simulated demo route
  },

  /* ── MAP ────────────────────────────────────────────────── */
  map: {
