Object.freeze(CONFIG);
Object.freeze(CONFIG.cafe);
Object.freeze(CONFIG.restaurant);
Object.freeze(CONFIG.delivery);
Object.freeze(CONFIG.tax);
Object.freeze(CONFIG.supabase);
