export default CONFIG;

/**
 * ╔══════════════════════════════════════════════════════════╗
 * ║  BREW & BLOOM CAFÉ — CART ENGINE                        ║
 * ║  Handles cart state, localStorage persistence,          ║
 * ║  delivery fee and tax calculation.                       ║
 * ╚══════════════════════════════════════════════════════════╝
 */

import CONFIG from './config.js';
import { getItemById } from './menu-data.js';

const STORAGE_KEY = 'bnb_cart_v2';

/** @returns {CartItem[]} */
function loadCart() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
}

function saveCart(items) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(items));
}

// ── Internal reactive state ────────────────────────────────
let _items = loadCart();
const _listeners = new Set();

function notify() {
  _listeners.forEach(fn => fn(getSnapshot()));
}

// ── Public API ─────────────────────────────────────────────

/**
 * Subscribe to cart changes.
 * @param {(snapshot: CartSnapshot) => void} fn
 * @returns {() => void} unsubscribe
 */
export function subscribe(fn) {
  _listeners.add(fn);
  fn(getSnapshot()); // immediate call with current state
  return () => _listeners.delete(fn);
}

/** Add one unit of item (by id) to cart. */
export function addItem(itemId) {
  const product = getItemById(itemId);
  if (!product || !product.available) return false;

  const existing = _items.find(i => i.id === itemId);
  if (existing) {
    existing.qty += 1;
  } else {
    _items.push({ id: itemId, name: product.name, price: product.price, qty: 1, emoji: product.emoji });
  }
  saveCart(_items);
  notify();
  return true;
}

/** Decrease quantity by 1; removes item if qty reaches 0. */
export function decreaseItem(itemId) {
  const idx = _items.findIndex(i => i.id === itemId);
  if (idx === -1) return;
  _items[idx].qty -= 1;
  if (_items[idx].qty <= 0) _items.splice(idx, 1);
  saveCart(_items);
  notify();
}

/** Remove item entirely. */
export function removeItem(itemId) {
  _items = _items.filter(i => i.id !== itemId);
  saveCart(_items);
  notify();
}

/** Clear all items. */
export function clearCart() {
  _items = [];
  saveCart(_items);
  notify();
}

/**
 * Get quantity of a specific item in cart.
 * @param {string} itemId
 * @returns {number}
 */
export function getQty(itemId) {
  return _items.find(i => i.id === itemId)?.qty ?? 0;
}

/**
 * Build a full snapshot with all calculated totals.
 * @param {number} [deliveryDistanceKm=0]
 * @returns {CartSnapshot}
 */
export function getSnapshot(deliveryDistanceKm = 0) {
  const items = structuredClone(_items);
  const subtotal = items.reduce((s, i) => s + i.price * i.qty, 0);
  const itemCount = items.reduce((s, i) => s + i.qty, 0);

  const d = CONFIG.delivery;
  let deliveryCharge = 0;

  if (subtotal > 0) {
    if (subtotal >= d.freeAbove && deliveryDistanceKm <= d.freeRadiusKm) {
      deliveryCharge = 0;
    } else {
      deliveryCharge = d.baseCharge;
      if (deliveryDistanceKm > d.freeRadiusKm) {
        deliveryCharge += Math.ceil(deliveryDistanceKm - d.freeRadiusKm) * d.perKmCharge;
      }
    }
  }

  const gstAmount   = Math.round(subtotal * CONFIG.tax.gstPercent / 100);
  const total       = subtotal + deliveryCharge + gstAmount;

  return { items, itemCount, subtotal, deliveryCharge, gstAmount, total, gstPercent: CONFIG.tax.gstPercent };
}

/**
 * Estimate delivery time (minutes) given distance in km.
 * @param {number} distanceKm
 * @returns {number} minutes
 */
export function estimateDeliveryTime(distanceKm) {
  return CONFIG.delivery.estimatedMinBase + Math.ceil(distanceKm * CONFIG.delivery.perKmMinutes);
}

/**
 * ╔══════════════════════════════════════════════════════════╗
 * ║  BREW & BLOOM CAFÉ — SUPABASE CLIENT                    ║
 * ║  Initialises Supabase. Falls back to demo mode if       ║
 * ║  credentials are not configured.                        ║
 * ╚══════════════════════════════════════════════════════════╝
 */

import CONFIG from './config.js';

let _supabase = null;
export let DEMO_MODE = true;

/**
 * Initialise the Supabase client. Safe to call multiple times.
 * Returns null in demo mode.
 */
export async function initSupabase() {
  if (_supabase) return _supabase;

  const { url, anonKey } = CONFIG.supabase;
  if (!url || !anonKey) {
    console.info('[BrewBloom] Supabase not configured → running in demo mode.');
    DEMO_MODE = true;
    return null;
  }

  try {
    // Supabase v2 is loaded via CDN script tag — window.supabase is available
    if (!window.supabase) throw new Error('Supabase CDN not loaded');
    _supabase = window.supabase.createClient(url, anonKey);
    DEMO_MODE = false;
    console.info('[BrewBloom] Supabase connected.');
    return _supabase;
  } catch (err) {
    console.warn('[BrewBloom] Supabase init failed → demo mode.', err.message);
    DEMO_MODE = true;
    return null;
  }
}

export function getClient() { return _supabase; }

// ── ORDER FUNCTIONS ─────────────────────────────────────────

/**
 * Place a new order.
 * In demo mode: saves to localStorage and returns a fake order.
 */
export async function placeOrder(orderData) {
  if (DEMO_MODE) return placeDemoOrder(orderData);

  const sb = getClient();
  const { data, error } = await sb.from('orders').insert([orderData]).select().single();
  if (error) throw error;
  return data;
}

/**
 * Get order by id and token (prevents unauthorised access).
 */
export async function getOrder(orderId, token) {
  if (DEMO_MODE) return getDemoOrder(orderId);

  const sb = getClient();
  const { data, error } = await sb
    .from('orders')
    .select('*, order_items(*)')
    .eq('id', orderId)
    .eq('tracking_token', token)
    .single();
  if (error) throw error;
  return data;
}

/**
 * Subscribe to real-time driver location for an order.
 * Returns an unsubscribe function.
 */
export function subscribeToDriverLocation(orderId, onUpdate) {
  if (DEMO_MODE) return () => {};

  const sb = getClient();
  const channel = sb
    .channel(`driver-location-${orderId}`)
    .on('postgres_changes', {
      event: 'UPDATE',
      schema: 'public',
      table: 'driver_locations',
      filter: `order_id=eq.${orderId}`,
    }, payload => onUpdate(payload.new))
    .subscribe();

  return () => sb.removeChannel(channel);
}

/**
 * Driver: push location update.
 */
export async function pushDriverLocation(orderId, lat, lng) {
  if (DEMO_MODE) return;
  const sb = getClient();
  await sb.from('driver_locations').upsert({ order_id: orderId, lat, lng, updated_at: new Date().toISOString() });
}

/**
 * Admin: get all orders.
 */
export async function getAdminOrders() {
  if (DEMO_MODE) return getDemoAdminOrders();
  const sb = getClient();
  const { data, error } = await sb
    .from('orders')
    .select('*, order_items(*)')
    .order('created_at', { ascending: false });
  if (error) throw error;
  return data;
}

/**
 * Admin: update order status.
 */
export async function updateOrderStatus(orderId, status) {
  if (DEMO_MODE) return updateDemoOrderStatus(orderId, status);
  const sb = getClient();
  const { error } = await sb
    .from('orders')
    .update({ status, updated_at: new Date().toISOString() })
    .eq('id', orderId);
  if (error) throw error;
}

// ── DEMO MODE HELPERS ───────────────────────────────────────
const DEMO_ORDERS_KEY = 'bnb_demo_orders_v2';

function genOrderId() {
  return 'BNB' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2,5).toUpperCase();
}

function genToken() {
  return Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
}

function placeDemoOrder(orderData) {
  const orderId = genOrderId();
  const token   = genToken();
  const order = {
    ...orderData,
    id: orderId,
    tracking_token: token,
    status: 'received',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    is_demo: true,
  };
  const existing = getDemoOrders();
  existing.unshift(order);
  localStorage.setItem(DEMO_ORDERS_KEY, JSON.stringify(existing));
  return order;
}

function getDemoOrder(orderId) {
  return getDemoOrders().find(o => o.id === orderId) || null;
}

function getDemoOrders() {
  try { return JSON.parse(localStorage.getItem(DEMO_ORDERS_KEY) || '[]'); } catch { return []; }
}

function getDemoAdminOrders() {
  return getDemoOrders();
}

function updateDemoOrderStatus(orderId, status) {
  const orders = getDemoOrders();
  const o = orders.find(o => o.id === orderId);
  if (o) {
    o.status = status;
    o.updated_at = new Date().toISOString();
    localStorage.setItem(DEMO_ORDERS_KEY, JSON.stringify(orders));
  }
}

