602: function updateCheckoutLocation(lat, lng, note = '') {
603:   const cafeLat = CONFIG.restaurant.lat;
604:   const cafeLng = CONFIG.restaurant.lng;
605: 
606:   if (state.checkoutUserMarker) {
607:     state.checkoutUserMarker.setLatLng([lat, lng]);
608:   }
609: 
610:   // Calculate straight-line distance
611:   const dLat = (lat - cafeLat) * (Math.PI / 180);
612:   const dLng = (lng - cafeLng) * (Math.PI / 180);
613:   const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
614:             Math.cos(cafeLat * (Math.PI / 180)) * Math.cos(lat * (Math.PI / 180)) *
615:             Math.sin(dLng / 2) * Math.sin(dLng / 2);
616:   const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
617:   const straightDistanceKm = Math.round(6371 * c * 10) / 10;
618: 
619:   // Road distance is typically ~1.25x straight line
620:   const approxRoadDistanceKm = Math.round(straightDistanceKm * 1.25 * 10) / 10;
