async function handleOrderSubmit(e) {
  e.preventDefault();

  const nameInput = document.getElementById('custName');
  const phoneInput = document.getElementById('custPhone');
  const addrInput = document.getElementById('custAddress');
  const localInput = document.getElementById('custLocality');
  const pinInput = document.getElementById('custPin');
  const notesInput = document.getElementById('custNotes');
  const paymentMethod = document.querySelector('input[name="paymentMethod"]:checked')?.value || 'cod';

  // Validation
  let isValid = true;

  if (!nameInput.value.trim()) {
    nameInput.classList.add('invalid');
    isValid = false;
  } else {
    nameInput.classList.remove('invalid');
  }

  // Indian mobile validation (10 digits starting with 6-9)
  const phoneVal = phoneInput.value.trim().replace(/\D/g, '');
  if (!/^[6-9]\d{9}$/.test(phoneVal)) {
    phoneInput.classList.add('invalid');
    isValid = false;
  } else {
    phoneInput.classList.remove('invalid');
  }

  if (state.deliveryMode === 'delivery') {
    if (!addrInput.value.trim()) {
      addrInput.classList.add('invalid');
      isValid = false;
    } else {
      addrInput.classList.remove('invalid');
    }

    if (!localInput.value.trim()) {
      localInput.classList.add('invalid');
      isValid = false;
    } else {
      localInput.classList.remove('invalid');
    }

    if (!/^\d{6}$/.test(pinInput.value.trim())) {
      pinInput.classList.add('invalid');
      isValid = false;
    } else {
      pinInput.classList.remove('invalid');
    }

    if (state.customerDistanceKm > CONFIG.delivery.radiusKm) {
      showToast(`Delivery is only available within ${CONFIG.delivery.radiusKm} km. Please select Takeaway or Dine-in.`, 'error');
      return;
    }
  }

  if (!isValid) {
    showToast('Please fix the errors highlighted in red.', 'error');
    return;
  }

  const snapshot = getSnapshot(state.deliveryMode === 'delivery' ? state.customerDistanceKm : 0);

  if (snapshot.items.length === 0) {
    showToast('Your cart is empty!', 'error');
    return;
  }

  const confirmBtn = document.getElementById('confirmOrderBtn');
  if (confirmBtn) {
    confirmBtn.disabled = true;
    confirmBtn.textContent = 'Processing your order...';
  }

  const orderData = {
    customer_name: nameInput.value.trim(),
    customer_phone: phoneVal,
    order_mode: state.deliveryMode,
    delivery_address: state.deliveryMode === 'delivery'
      ? `${addrInput.value.trim()}, ${localInput.value.trim()}, Haldia - ${pinInput.value.trim()}`
      : 'Self Pickup / Dine-in at Haldia Café',
    customer_lat: state.customerLat,
    customer_lng: state.customerLng,
    customer_distance_km: state.deliveryMode === 'delivery' ? state.customerDistanceKm : 0,
    special_instructions: notesInput?.value.trim() || '',
    payment_method: paymentMethod,
    subtotal: snapshot.subtotal,
    tax_amount: snapshot.gstAmount,
    delivery_charge: state.deliveryMode === 'delivery' ? snapshot.deliveryCharge : 0,
    total_amount: state.deliveryMode === 'delivery' ? snapshot.total : snapshot.subtotal + snapshot.gstAmount,
    items: snapshot.items,
    status: 'received',
  };

  try {
    const createdOrder = await placeOrder(orderData);
    clearCart();
    closeCheckoutModal();

    showToast(`Order #${createdOrder.id} placed successfully!`, 'success');

    // Forward to dedicated Live Order Tracking page!
    setTimeout(() => {
      window.location.href = `order-tracking.html?orderId=${createdOrder.id}`;
    }, 1200);
  } catch (err) {
    console.error('Order error:', err);
    showToast('Could not record order: ' + (err.message || 'Unknown error'), 'error');
    if (confirmBtn) {
      confirmBtn.disabled = false;
      confirmBtn.textContent = 'Place Order Now →';
    }
  }
}

